; Wait A seconds (seconds counts them). Every wait routine resets
; the stack and starts a game if a console key was pressed.
WaitSecs	sta wait_secs
        	lda #$00
        	sta seconds
        	lda wait_secs
L2ED4   	cmp seconds
        	beq L2EE4
        	ldx console
        	bpl L2ED4
        	ldx #$FF
        	txs
        	jmp StartPressed
L2EE4   	rts

