; Set up a new game, then run the main loop: the screen's own
; work (typing at the ticket counter, the InfoBooth, or the agent),
; people, drawing, sparkles, crystals growing, hourly fuzz.
NewGame 	jsr SetupGame
MainLoop	lda screen
        	cmp #$02
        	bne L3C34
        	jsr TicketInput
        	jsr DrawTimetable
L3C34   	lda screen              ; the InfoBooth has its own loop
        	cmp #$05
        	bne L3C41
        	jsr RunBooth
        	jmp L3C44
L3C41   	jsr AgentUpdate
L3C44   	jsr PeopleUpdate
        	lda console
        	bmi L3C83
        	jsr DrawObjects
        	dec tick6               ; every 6th pass
        	bne L3C5F
        	lda #$06
        	sta tick6
        	jsr AnimSparkles
        	jsr PrintCrystals
L3C5F   	dec ai_turn
        	bne L3C69
        	lda #$0A
        	sta ai_turn
L3C69   	dec tick15              ; every 15th pass
        	bne L3C76
        	lda #$0F
        	sta tick15
        	jsr GrowCrystals
L3C76   	lda hour_tick
        	beq L3C83
        	jsr HourlyFuzz
        	lda #$00
        	sta hour_tick
L3C83   	jmp MainLoop

