; Lose if there are no crystals left anywhere: none lying in the
; station, nobody carrying any, and no city with crystals.
CheckAllFuzzed	pha
        	txa
        	pha
        	ldx #$00
        	lda cr_next,x
        	bne L3E6F
        	ldx #$0B
        	lda obj_state,x
        	cmp #$08
        	bcc L3E6F
