        	bne L3E6F
        	dex
        	bne L3E5A
        	ldx #$64
L3E64   	lda city_crystals,x
        	bpl L3E6F
        	dex
        	bne L3E64
        	jmp GameLost
L3E6F   	pla
        	tax
        	pla
        	rts
GameLost	jsr SoundOff            ; all is lost: the "Alas" screen, wait for a key
        	lda #$01
        	sta game_over
        	lda #$00
        	sta clock_stop
        	lda #$08
