        	lda #$FF
        	sta CH
L3E8A   	lda CH
        	cmp #$FF
        	beq L3E8A
        	ldx #$FF
        	txs
        	jmp NewGame

; Draw the walls of the current room: every wall that crosses
; the room window is clipped and drawn with DrawHLine/DrawVLine.
DrawWalls	lda room_x+1
        	sta wall_x+1
        	lda room_x
        	clc
        	adc #$07
        	sta wall_x
        	bcc L3EAB
        	inc wall_x+1
L3EAB   	lda nvwalls
        	asl
        	tay
L3EB0   	lda wall_vx+1,y
        	cmp wall_x+1
        	bne L3EBE
        	lda wall_vx,y
        	cmp wall_x
L3EBE   	bcc L3F3B
        	lda view+7
        	cmp wall_vx+1,y
        	bne L3ECC
        	lda view+6
        	cmp wall_vx,y
L3ECC   	bcc L3F3B
        	lda wall_vy2+1,y
