; Every game hour: fuzz spreads from every fuzzed city to its
; rail neighbours, and the FuzzBomb moves on.
HourlyFuzz	ldx #$64
L4C13   	cpx city
        	beq L4C20
        	lda city_crystals,x
        	bpl L4C20
        	jsr FuzzNeighbours
L4C20   	dex
        	bne L4C13
        	jsr MoveFuzzBomb
        	jsr CheckAllFuzzed
        	rts

FuzzNeighbours	txa
        	pha
        	asl
        	tay
        	lda city_links,y
        	sta ptr
        	lda city_links+1,y
        	sta ptr+1
        	ldy #$00
        	lda (ptr),y
L4C3C   	bmi L4C59
        	and #$7F
        	tax
        	lda city_crystals,x
        	bmi L4C59
        	beq L4C54
        	lda RANDOM
        	and #$0F
        	bne L4C59
        	dec city_crystals,x
        	bne L4C59
L4C54   	lda #$80
        	sta city_crystals,x
L4C59   	iny
        	iny
        	lda (ptr),y
        	bne L4C3C
        	pla
        	tax
        	rts

; The FuzzBomb travels along the rail links towards bomb_goal,
; fuzzing the cities on its way; bomb_timer hours per hop.
MoveFuzzBomb	lda bomb_here
        	bne L4C7C
        	dec bomb_timer
        	beq L4C6D
        	rts
L4C6D   	lda bomb_city
        	bpl L4C7D
