        	asl
        	tay
        	lda city_links,y
        	sta ptr
        	lda city_links+1,y
        	sta ptr+1
        	ldy #$00
        	sty ncand
L4C91   	lda (ptr),y
        	beq L4CBB
        	bmi L4CA2
        	cmp city
        	beq L4CA2
        	tax
        	lda city_crystals,x
        	bmi L4CA7
L4CA2   	iny
