        	sta obj_scr_hi,x
        	lda obj_scr_lo,x
        	asl
        	rol addr_tmp
        	asl
        	rol addr_tmp
        	clc
        	adc obj_scr_lo,x
        	sta obj_scr_lo,x
        	lda addr_tmp
        	adc obj_scr_hi,x
        	sta obj_scr_hi,x
        	lda obj_xl,x
        	sec
        	sbc view+4
        	and #$03
        	sta obj_subx,x
        	sta obj_old_subx,x
        	lda obj_xl,x
        	sec
        	sbc view+4
        	lsr
        	lsr
        	clc
        	adc obj_scr_lo,x
        	sta obj_scr_lo,x
        	bcc L7205
        	inc obj_scr_hi,x
L7205   	lda #$D0
