; ==================================================================
; Clock and calendar (one game second per second of real time)
; ==================================================================

; Once a second (VBI): clock, timetable every 15 seconds, sky
; colours every hour.
EverySecond	lda clock_stop
        	bne L72A7
        	inc secs15
        	lda secs15
        	cmp #$0F
        	bcc L7288
        	lda #$00
        	sta secs15
        	jsr TimetableStep
L7288   	jsr TickSeconds
        	bcc L72A7
        	jsr TickMinutes
        	bcc L72A7
        	jsr TickHours
        	lda #$01
        	sta hour_tick
        	jsr SkyColours
        	lda hours
        	cmp #$18
        	bcc L72A7
        	jsr NextDay
L72A7   	rts

TickSeconds	inc seconds
        	lda seconds
