        	sta status_line+5
        	lda minutes
L7300   	cmp #$0A
        	bcc L730D
        	sec
        	sbc #$0A
        	inc status_line+5
        	jmp L7300
L730D   	clc
        	adc #$10
        	sta status_line+6
        	rts

