; ==================================================================

; New game: 1-3 crystal units per city, the FuzzBomb in a random
; city (advanced game: until 50 cities are fuzzed), start in a
; random city away from it, 10 crystals, arriving by train.
SetupGame	lda #$00
        	sta SDMCTL
        	jsr ClearVars
        	jsr SetupColours
        	jsr TrainFromRight
        	jsr OpenKeyboard
        	lda #$01
        	sta clock_stop
