L7451   	dex
        	bne L744B
        	cpy #$32
        	bcc L7444
L7458   	ldy RANDOM              ; a random start city, not fuzzed, not next to the FuzzBomb
        	beq L7458
        	cpy #$65
        	bcs L7458
        	lda city_crystals,y
        	bmi L7458
        	sty city
        	jsr NearBomb
        	bcs L7458
        	jsr ArriveInCity
L7471   	lda RANDOM
        	beq L7471
        	cmp #$65
        	bcs L7471
        	sta bomb_goal
        	lda #$01
        	sta room
