        	lda #$03
        	sta SKCTL
        	ldx #$0B
        	lda #$00
        	sta obj_flags,x
        	sta obj_xh,x
        	sta obj_xl,x
        	sta obj_yh,x
        	sta obj_yl,x
        	lda #$06
        	sta obj_state,x
        	lda #$0A                ; the agent starts with 10 crystals
        	sta obj_crystals,x
        	jsr SoundOff
        	lda #$01
        	sta train_phase
        	lda #$00
        	sta clock_stop
        	sta game_over
        	sta fuzz_ride
        	lda #$40
        	sta console
        	jsr StatusOnTop
        	lda #$32
